diff --git a/mm/swap_state.c b/mm/swap_state.c
index 7ac1808ae..c30fb4bfb 100644
--- a/mm/swap_state.c
+++ b/mm/swap_state.c
@@ -718,6 +718,16 @@ void swap_update_readahead(struct folio *folio, struct vm_area_struct *vma,
 			hits = min_t(int, hits + 1, SWAP_RA_HITS_MAX);
 		atomic_long_set(&vma->swap_readahead_info,
 				SWAP_RA_VAL(addr, win, hits));
+	} else if (vma && readahead) {
+		/*
+		 * Cluster mode keeps its window in global state, so the VMA
+		 * history is only read by xswap_fault_readahead().  Record a
+		 * readahead hit there: the next miss after a prefetched block
+		 * is then adjacent and stays admitted.  The history is
+		 * advisory and every entry is revalidated by the swap cache.
+		 */
+		atomic_long_set(&vma->swap_readahead_info,
+				SWAP_RA_VAL(addr, 1, 0));
 	}

 	if (readahead) {
@@ -754,7 +764,70 @@ static struct folio *swap_cache_read_folio(struct swap_io_ctx *ctx,
 }

 /**
- * swapin_sync - swap-in one or multiple entries skipping readahead.
+ * xswap_readahead_wanted - Check whether an xswap slot has a physical backend.
+ * @si: the swap device of @entry.
+ * @entry: the swap entry, which need not be pinned.
+ *
+ * This is a readahead hint, not a pin on the slot or its backend. The swap
+ * cache allocation and read paths must revalidate the entry after this
+ * returns. No cluster pointer or physical entry escapes the lock.
+ *
+ * Context: Caller must protect @si with a reference count or locks.
+ * Return: true if an xswap slot has a physical backend, false otherwise.
+ */
+static bool xswap_readahead_wanted(struct swap_info_struct *si,
+				   swp_entry_t entry)
+{
+	struct swap_cluster_info *ci;
+	bool backed;
+
+	if (!(si->flags & SWP_XSWAP))
+		return false;
+	ci = swap_cluster_lock_unpinned(si, swp_offset(entry));
+	if (!ci)
+		return false;
+	backed = xswap_slot_backend(ci, swp_cluster_offset(entry)).val;
+	swap_cluster_unlock(ci);
+
+	return backed;
+}
+
+/**
+ * xswap_fault_readahead - Admit physical readahead after adjacent faults.
+ * @vmf: fault holding a reference to the target swap device.
+ * @entry: target swap entry.
+ *
+ * Keep discontinuous faults on the synchronous demand path. VMA history is
+ * advisory: racing faults may suppress or admit speculation, but the swap
+ * cache and I/O paths still validate every entry and own its references.
+ */
+static bool xswap_fault_readahead(struct vm_fault *vmf, swp_entry_t entry)
+{
+	struct swap_info_struct *si = __swap_entry_to_info(entry);
+	struct vm_area_struct *vma = vmf->vma;
+	unsigned long prev;
+
+	if (!(si->flags & SWP_XSWAP) || READ_ONCE(page_cluster) <= 0)
+		return false;
+	/* shmem passes its own vmf; its VMA has no swap PTEs to read ahead. */
+	if (vma_is_shmem(vma))
+		return false;
+	prev = SWAP_RA_ADDR(GET_SWAP_RA_VAL(vma));
+	if (vmf->address != prev + PAGE_SIZE &&
+	    prev != vmf->address + PAGE_SIZE) {
+		atomic_long_set(&vma->swap_readahead_info,
+				SWAP_RA_VAL(vmf->address, 1, 0));
+		return false;
+	}
+	/* VMA mode updates the history in swap_vma_ra_win(). */
+	if (!swap_use_vma_readahead())
+		atomic_long_set(&vma->swap_readahead_info,
+				SWAP_RA_VAL(vmf->address, 1, 0));
+	return xswap_readahead_wanted(si, entry);
+}
+
+/**
+ * swapin_sync - swap-in one or multiple entries, normally skipping readahead.
  * @entry: swap entry indicating the target slot
  * @gfp: memory allocation flags
  * @orders: allocation orders
@@ -765,6 +838,8 @@ static struct folio *swap_cache_read_folio(struct swap_io_ctx *ctx,
  * This allocates a folio suitable for given @orders, or returns the
  * existing folio in the swap cache for @entry. This initiates the IO, too,
  * if needed. @entry is rounded down if @orders allow large allocation.
+ * An order-0 fault on an xswap entry with a physical backend that follows
+ * an adjacent fault goes through swapin_readahead() instead.
  *
  * Context: Caller must ensure @entry is valid and pin the swap device with refcount.
  * Return: Returns the folio on success, error code if failed.
@@ -775,6 +850,12 @@ struct folio *swapin_sync(swp_entry_t entry, gfp_t gfp, unsigned long orders,
 	struct swap_io_ctx ctx = {};
 	struct folio *folio;

+	if (vmf && orders == BIT(0) && xswap_fault_readahead(vmf, entry)) {
+		folio = swapin_readahead(entry, gfp, vmf);
+		if (folio)
+			return folio;
+	}
+
 	do {
 		folio = swap_cache_get_folio(entry);
 		if (folio)
@@ -920,8 +1001,8 @@ struct folio *swap_cluster_readahead(swp_entry_t entry, gfp_t gfp_mask,
 	struct blk_plug plug;
 	swp_entry_t ra_entry;

-	/* xswap entries live only in zswap; readahead does not help. */
-	if (si->flags & SWP_XSWAP)
+	/* Keep compressed xswap targets on the single-folio path. */
+	if ((si->flags & SWP_XSWAP) && !xswap_readahead_wanted(si, entry))
 		goto skip;

 	mask = swapin_nr_pages(offset) - 1;
@@ -940,6 +1021,9 @@ struct folio *swap_cluster_readahead(swp_entry_t entry, gfp_t gfp_mask,
 	for (offset = start_offset; offset <= end_offset ; offset++) {
 		/* Ok, do the async read-ahead now */
 		ra_entry = swp_entry(swp_type(entry), offset);
+		if ((si->flags & SWP_XSWAP) && offset != entry_offset &&
+		    !xswap_readahead_wanted(si, ra_entry))
+			continue;
 		folio = swap_cache_read_folio(&ctx, ra_entry, gfp_mask, mpol,
 				ilx, offset != entry_offset);
 		if (!folio)
@@ -1009,7 +1093,6 @@ static int swap_vma_ra_win(struct vm_fault *vmf, unsigned long *start,
 static struct folio *swap_vma_readahead(swp_entry_t targ_entry, gfp_t gfp_mask,
 		struct mempolicy *mpol, pgoff_t targ_ilx, struct vm_fault *vmf)
 {
-	struct swap_info_struct *si = __swap_entry_to_info(targ_entry);
 	struct swap_io_ctx ctx = {};
 	struct blk_plug plug;
 	struct folio *folio;
@@ -1018,10 +1101,6 @@ static struct folio *swap_vma_readahead(swp_entry_t targ_entry, gfp_t gfp_mask,
 	unsigned long start, end, addr;
 	pgoff_t ilx = targ_ilx;

-	/* xswap entries live only in zswap; readahead does not help. */
-	if (si->flags & SWP_XSWAP)
-		goto skip;
-
 	win = swap_vma_ra_win(vmf, &start, &end);
 	if (win == 1)
 		goto skip;
@@ -1054,8 +1133,13 @@ static struct folio *swap_vma_readahead(swp_entry_t targ_entry, gfp_t gfp_mask,
 			if (IS_ERR_OR_NULL(si))
 				continue;
 		}
-		folio = swap_cache_read_folio(&ctx, entry, gfp_mask, mpol, ilx,
-					      addr != vmf->address);
+		if (addr != vmf->address &&
+		    (__swap_entry_to_info(entry)->flags & SWP_XSWAP) &&
+		    !xswap_readahead_wanted(__swap_entry_to_info(entry), entry))
+			folio = NULL;
+		else
+			folio = swap_cache_read_folio(&ctx, entry, gfp_mask, mpol,
+						      ilx, addr != vmf->address);
 		if (si)
 			put_swap_device(si);
 		if (!folio)

